const I='@@/';
const SVGNS='http://www.w3.org/2000/svg';

/* ---------- construção do logo: guias, contorno, vértices, preenchimento ---------- */
function buildLogo(o){
 // o: {logo, bg, ink, ink2, accent, caps:{tl,tr,bl,br}, extra}
 const L=LOGOS[o.logo], pad=o.pad||90;
 let vb=o.vb||[-pad,-pad,L.w+pad*2,L.h+pad*2];
 const vxSize=Math.max(vb[2],vb[3])/120;
 let s=`<svg viewBox="${vb.join(' ')}" aria-hidden="true">`;
 [0,L.h/2,L.h].forEach((y,i)=>s+=`<line class="g gl" pathLength="1" x1="${vb[0]}" x2="${vb[0]+vb[2]}" y1="${y}" y2="${y}" stroke="${o.accent}" style="animation-delay:${i*.1}s"/>`);
 if(o.extra)s+=o.extra(L);
 let n=0, end=0;
 if(L.L){
  // letra por letra: linhas, contorno, vértices e preenchimento
  const N=L.L.length, gap=Math.min(.24,1.8/N);
  L.L.forEach((Q,i)=>{const b=Q.b, t0=.25+i*gap, ink=Q.g?o.ink2:o.ink;
   s+=`<line class="g gl" pathLength="1" y1="${vb[1]}" y2="${vb[1]+vb[3]}" x1="${b[0]}" x2="${b[0]}" stroke="${o.accent}" style="animation-delay:${t0.toFixed(2)}s"/>`;
   s+=`<line class="g gl" pathLength="1" y1="${vb[1]}" y2="${vb[1]+vb[3]}" x1="${b[2]}" x2="${b[2]}" stroke="${o.accent}" style="animation-delay:${(t0+.08).toFixed(2)}s;opacity:.3"/>`;
   s+=`<rect class="g gl" pathLength="1" x="${b[0]}" y="${b[1]}" width="${b[2]-b[0]}" height="${b[3]-b[1]}" stroke="${o.accent}" style="animation-delay:${(t0+.1).toFixed(2)}s;stroke-dasharray:1;opacity:.7"/>`;
   s+=`<path class="ol" pathLength="1" d="${Q.d}" stroke="${ink}" style="animation-delay:${(t0+.15).toFixed(2)}s;animation-duration:1.1s"/>`;
   const fs=1.5+N*gap*.55+i*.11; end=Math.max(end,fs+.6);
   s+=`<path class="fl" d="${Q.d}" fill="${ink}" fill-rule="evenodd" style="animation-delay:${fs.toFixed(2)}s;animation-duration:.6s"/>`;
   const step=Math.max(1,Math.round(Q.v.length/14));
   s+=`<g class="vx" style="animation-delay:${(fs+.3).toFixed(2)}s">`;
   Q.v.filter((_,j)=>j%step===0).forEach((p,j,arr)=>s+=`<rect x="${p[0]-vxSize/2}" y="${p[1]-vxSize/2}" width="${vxSize}" height="${vxSize}" fill="${o.bg}" stroke="${o.accent}" stroke-width="1.2" vector-effect="non-scaling-stroke" style="animation-delay:${(t0+.35+j*.5/arr.length).toFixed(2)}s"/>`);
   s+='</g>';n+=Q.v.length;
  });
 }else{
  [0,L.w].forEach((x,i)=>s+=`<line class="g gl" pathLength="1" y1="${vb[1]}" y2="${vb[1]+vb[3]}" x1="${x}" x2="${x}" stroke="${o.accent}" style="animation-delay:${.3+i*.12}s"/>`);
  const v=L.v, step=Math.max(1,Math.round(v.length/70)), pick=v.filter((_,i)=>i%step===0);
  if(L.stroke){ // assinatura: traço que se escreve
   const parts=L.d.split('M').filter(Boolean);
   let w=.6; s+='<g class="sig">';
   parts.forEach(p=>{const len=Math.max(.35,p.length/900);s+=`<path pathLength="1" d="M${p}" stroke="${o.ink}" stroke-width="${o.sw||L.stroke*.8}" style="--d:${len}s;--w:${w}s"/>`;w+=len*.85});
   s+='</g>';
  }else{
   s+=`<path class="ol" pathLength="1" d="${L.d}" stroke="${o.ink}"/><path class="fl" d="${L.d}" fill="${o.ink}" fill-rule="evenodd"/>`;
  }
  s+='<g class="vx">';
  pick.forEach((p,i)=>s+=`<rect x="${p[0]-vxSize/2}" y="${p[1]-vxSize/2}" width="${vxSize}" height="${vxSize}" fill="${o.bg}" stroke="${o.accent}" stroke-width="1.2" vector-effect="non-scaling-stroke" style="animation-delay:${(1.1+i*1.3/pick.length).toFixed(2)}s"/>`);
  s+='</g>';n=v.length;
 }
 s+='</svg>';
 const c=o.caps||{};
 const cap=(k,cls)=>c[k]?`<span class="cap ${k} ${cls||''}" style="color:${o.accent}">${c[k].replace('{n}',n)}</span>`:'';
 return `<div class="build in" style="background:${o.bg}">${s}${cap('tl')}${cap('tr')}${cap('bl','late')}${cap('br','late')}</div>`;
}

/* ---------- movimentos de construção: um jeito diferente por marca ---------- */
let UID=0;
const lettersOf=L=>L.L||[{d:L.d,v:L.v,b:[0,0,L.w,L.h],g:0}];
const npts=d=>(d.match(/L/g)||[]).length+1;
const capsHTML=(o,n)=>{const c=o.caps||{},k=c.tr||c.tl;return k?`<span class="cap bl" style="color:${o.accent}">${k.replace('{n}',n)}</span>`:''};
function motion(o){
 const L=LOGOS[o.logo], pad=o.pad||90, id='u'+(UID++);
 const vb=o.vb||[-pad,-pad,L.w+pad*2,L.h+pad*2];
 const LL=lettersOf(L), n=LL.reduce((a,q)=>a+q.v.length,0);
 const ink=q=>q.g?o.ink2:o.ink;
 let s=`<svg viewBox="${vb.join(' ')}" aria-hidden="true">`, extra='';
 if(o.mode==='close'){
  // close extremo: a câmera começa colada num detalhe e abre até mostrar a marca
  const S=o.zoom||7, f=o.focus||[LL[0].b[0]+(LL[0].b[2]-LL[0].b[0])*.18,LL[0].b[1]+(LL[0].b[3]-LL[0].b[1])*.12];
  const cx=vb[0]+vb[2]/2, cy=vb[1]+vb[3]/2;
  s+=`<g class="cam" style="--from:translate(${(cx-S*f[0]).toFixed(1)}px,${(cy-S*f[1]).toFixed(1)}px) scale(${S});--hold:${o.hold||1.7}s">`;
  s+=`<line class="xh" x1="${vb[0]-vb[2]}" x2="${vb[0]+vb[2]*2}" y1="${f[1]}" y2="${f[1]}" stroke="${o.accent}"/><line class="xh" y1="${vb[1]-vb[3]}" y2="${vb[1]+vb[3]*2}" x1="${f[0]}" x2="${f[0]}" stroke="${o.accent}"/>`;
  [0,L.h].forEach((y,i)=>s+=`<line class="g gl" pathLength="1" x1="${vb[0]}" x2="${vb[0]+vb[2]}" y1="${y}" y2="${y}" stroke="${o.accent}" style="animation-delay:${2.2+i*.15}s"/>`);
  if(L.stroke){
   let w=.3;s+='<g class="sig">';
   L.d.split('M').filter(Boolean).forEach((p,i)=>{const len=i===0?1.8:Math.max(.3,p.length/1300);s+=`<path pathLength="1" d="M${p}" stroke="${o.ink}" stroke-width="2.4" vector-effect="non-scaling-stroke" style="--d:${len}s;--w:${w}s"/>`;w+=len*.9});
   s+='</g>';
  }else{
   const vs=vb[2]/(110*S)*1.8;
   LL.forEach((q,i)=>{const first=i===(o.fi||0), t0=first?.2:1.9+i*.12, du=first?2.6:1.2, fs=3.4+i*.09;
    s+=`<path class="ol" pathLength="1" d="${q.d}" stroke="${ink(q)}" style="animation-delay:${t0}s;animation-duration:${du}s;animation-timing-function:cubic-bezier(.45,0,.2,1)"/>`;
    s+=`<path class="fl" d="${q.d}" fill="${ink(q)}" fill-rule="evenodd" style="animation-delay:${fs.toFixed(2)}s;animation-duration:.7s"/>`;
    if(first){s+=`<g class="vx" style="animation-delay:3s">`;q.v.forEach((p,j)=>s+=`<rect x="${p[0]-vs/2}" y="${p[1]-vs/2}" width="${vs}" height="${vs}" fill="${o.bg}" stroke="${o.accent}" stroke-width="1" vector-effect="non-scaling-stroke" style="animation-delay:${(.5+j*1.4/q.v.length).toFixed(2)}s"/>`);s+='</g>'}
   });
  }
  s+='</g>';
  extra='';void `<span class="ticks" style="color:${o.accent}">x ${String(Math.round(f[0])).padStart(4,'0')} · y ${String(Math.round(f[1])).padStart(4,'0')}<br>${o.tick||'detalhe · '+S+'×'}</span>`;
 }else if(o.mode==='orbit'){
  // o ponto dá a volta no círculo e cai no lugar do O
  const R=o.ring, c=[R[0],R[1]];
  s+=`<circle class="g gl ring" pathLength="1" cx="${c[0]}" cy="${c[1]}" r="${R[2]}" stroke="${o.ink}" style="opacity:.85;stroke-dasharray:1;stroke-width:1.4"/>`;
  s+=`<g class="orb" style="transform-origin:${c[0]}px ${c[1]}px"><line x1="${c[0]}" y1="${c[1]}" x2="${c[0]+R[2]}" y2="${c[1]}" stroke="${o.accent}" stroke-width="1" vector-effect="non-scaling-stroke" opacity=".6"/><circle cx="${c[0]+R[2]}" cy="${c[1]}" r="16" fill="${o.ink}"/></g>`;
  LL.forEach((q,i)=>{const isDot=i===o.dot;
   s+=`<path class="${isDot?'popin':'blurin'}" d="${q.d}" fill="${ink(q)}" fill-rule="evenodd" style="animation-delay:${isDot?3:(1.2+i*.14).toFixed(2)}s"/>`});
 }else if(o.mode==='pen'){
  // traço contínuo e depois o degradê passa por cima
  const tot=LL.reduce((a,q)=>a+npts(q.d),0);let w=.2;
  const grad=o.grad;
  s+=`<defs><linearGradient id="${id}g" x1="0" x2="1">${grad.map((c,i)=>`<stop offset="${i/(grad.length-1)}" stop-color="${c}"/>`).join('')}</linearGradient><clipPath id="${id}c"><rect class="sweep" x="-10" y="-10" width="${L.w+20}" height="${L.h+20}" style="--sw:2.5s;--sd:1.3s"/></clipPath></defs>`;
  s+=`<line class="g gl" pathLength="1" x1="${vb[0]}" x2="${vb[0]+vb[2]}" y1="${L.h}" y2="${L.h}" stroke="${o.accent}"/>`;
  LL.forEach(q=>{const du=2.2*npts(q.d)/tot;s+=`<path class="ol" pathLength="1" d="${q.d}" stroke="${ink(q)}" style="animation-delay:${w.toFixed(2)}s;animation-duration:${du.toFixed(2)}s;animation-timing-function:linear"/>`;w+=du});
  s+=`<g clip-path="url(#${id}c)"><path d="${LL.map(q=>q.d).join(' ')}" fill="url(#${id}g)" fill-rule="evenodd"/></g>`;
  s+=`<path class="fl" d="${LL.map(q=>q.d).join(' ')}" fill="${o.ink}" fill-rule="evenodd" style="animation-delay:4.1s;animation-duration:1s"/>`;
 }else if(o.mode==='scan'){
  // uma luz passa e acende as letras, com lâmpadas de parque
  const x0=-40,x1=L.w+40;
  s+=`<defs><clipPath id="${id}c"><rect class="sweep" x="-10" y="-30" width="${L.w+20}" height="${L.h+60}" style="--sw:1.2s;--sd:2.2s"/></clipPath><filter id="${id}f" x="-2" y="-1" width="5" height="3"><feGaussianBlur stdDeviation="8"/></filter></defs>`;
  LL.forEach((q,i)=>s+=`<path class="ol" pathLength="1" d="${q.d}" stroke="${o.accent}" style="animation-delay:${(.1+i*.05).toFixed(2)}s;animation-duration:.9s;opacity:.6"/>`);
  s+=`<g clip-path="url(#${id}c)"><path d="${L.d}" fill="${o.ink}" fill-rule="evenodd"/></g>`;
  const gap=L.w/24;for(let k=0;k<=24;k++){const x=k*gap,dl=(1.2+2.2*(x+10)/(L.w+20)).toFixed(2);[-34,L.h+34].forEach(y=>s+=`<circle class="bulb" cx="${x}" cy="${y}" r="5" fill="${o.accent}" style="animation-delay:${dl}s"/>`)}
  s+=`<g class="bar-l" style="--x0:${x0}px;--x1:${x1}px;--sw:1.2s;--sd:2.2s"><rect x="-6" y="-60" width="12" height="${L.h+120}" fill="${o.accent}" filter="url(#${id}f)"/><rect x="-1.5" y="-60" width="3" height="${L.h+120}" fill="#fff"/></g>`;
 }else if(o.mode==='rise'){
  // cada letra sobe da linha de base, uma de cada vez
  s+=`<defs><clipPath id="${id}c"><rect x="${vb[0]}" y="${vb[1]}" width="${vb[2]}" height="${L.h-vb[1]+2}"/></clipPath></defs>`;
  s+=`<line class="g gl" pathLength="1" x1="${vb[0]}" x2="${vb[0]+vb[2]}" y1="${L.h}" y2="${L.h}" stroke="${o.accent}" style="stroke-dasharray:1;opacity:.9"/>`;
  s+=`<g clip-path="url(#${id}c)">`;
  LL.forEach((q,i)=>s+=`<path class="rise" d="${q.d}" fill="${ink(q)}" fill-rule="evenodd" style="--dy:${(L.h*1.15).toFixed(0)}px;animation-delay:${(.7+i*.1).toFixed(2)}s"/>`);
  s+='</g>';
  LL.forEach((q,i)=>{const b=q.b;s+=`<line class="g gl" pathLength="1" x1="${b[0]}" x2="${b[0]}" y1="${L.h+18}" y2="${L.h+40}" stroke="${o.accent}" style="animation-delay:${(.9+i*.1).toFixed(2)}s;opacity:.8;stroke-dasharray:1"/>`});
 }else if(o.mode==='spring'){
  // o símbolo gira e abre, as letras saltam no lugar
  const sym=LL.filter(q=>q.g), txt=LL.filter(q=>!q.g);
  sym.forEach(q=>{const b=q.b,cx=(b[0]+b[2])/2,cy=(b[1]+b[3])/2,r=(b[2]-b[0])/2;
   for(let k=0;k<3;k++)s+=`<circle class="echo" cx="${cx}" cy="${cy}" r="${r}" stroke="${o.ink2}" stroke-width="2" vector-effect="non-scaling-stroke" style="animation-delay:${(1+k*.35).toFixed(2)}s"/>`;
   s+=`<path class="twist" d="${q.d}" fill="${o.ink2}" fill-rule="evenodd" style="animation-delay:.2s"/>`});
  txt.forEach((q,i)=>s+=`<path class="spring" d="${q.d}" fill="${o.ink}" fill-rule="evenodd" style="animation-delay:${(1.3+i*.13).toFixed(2)}s"/>`);
 }
 s+='</svg>';
 return `<div class="build in" data-dur="${o.mode==='close'?7000:6200}" style="background:${o.bg}">${s}${extra}${capsHTML(o,n)}</div>`;
}
const imgs=(list,cls)=>list.map((f,i)=>`<div class="${cls[i]||cls[0]} in${i?' d'+i:''}"><img src="${I+f}" alt=""></div>`).join('');
const palette=cols=>`<div class="pal">${cols.map((c,i)=>`<div class="${i?'':'on'}" style="--i:${i};background:${c[1]};color:${c[2]||'#111'};${c[1].toUpperCase()==='#FFFFFF'?'box-shadow:inset 0 0 0 1px #EDEDED':''}"><span class="nm">${c[0]}</span><span>${c[1]}${c[3]?' · '+c[3]:''}</span></div>`).join('')}</div>`;

